const crypto = require('crypto');
const entrada = $input.first();
const segredo = $env.SLACK_SIGNING_SECRET;
if (!segredo) throw new Error('SLACK_SIGNING_SECRET indisponível no ambiente.');
const headers = Object.fromEntries(Object.entries(entrada.json.headers ?? {}).map(([nome, valor]) => [nome.toLowerCase(), valor]));
const timestamp = headers['x-slack-request-timestamp'];
const assinatura = headers['x-slack-signature'];
if (typeof timestamp !== 'string' || !/^\d+$/.test(timestamp) ||
    typeof assinatura !== 'string' || !/^v0=[0-9a-f]{64}$/.test(assinatura)) {
  throw new Error('Cabeçalhos de assinatura Slack inválidos.');
}
const segundos = Number(timestamp);
if (!Number.isSafeInteger(segundos) || Math.abs(Date.now() / 1000 - segundos) > 300) {
  throw new Error('Requisição Slack fora da janela de cinco minutos.');
}
if (!entrada.binary?.data) throw new Error('Corpo bruto indisponível no webhook.');
const corpo = await this.helpers.getBinaryDataBuffer(0, 'data');
const esperada = 'v0=' + crypto.createHmac('sha256', segredo).update('v0:' + timestamp + ':').update(corpo).digest('hex');
const recebido = Buffer.from(assinatura, 'utf8');
const calculado = Buffer.from(esperada, 'utf8');
if (recebido.length !== calculado.length || !crypto.timingSafeEqual(recebido, calculado)) {
  throw new Error('Assinatura Slack inválida.');
}
const envelope = JSON.parse(corpo.toString('utf8'));
if (!envelope || typeof envelope !== 'object' || Array.isArray(envelope)) {
  throw new Error('Envelope Slack inválido.');
}
if (!['url_verification', 'event_callback'].includes(envelope.type)) {
  throw new Error('Tipo de envelope Slack não suportado.');
}
if (envelope.type === 'url_verification' && (typeof envelope.challenge !== 'string' || !envelope.challenge || envelope.challenge.length > 4096)) {
  throw new Error('Challenge Slack inválido.');
}
return [{ json: { meta: { assinatura_verificada: true, recebido_em: new Date().toISOString() }, envelope } }];

const entrada = $input.first().json;
if (entrada.meta?.assinatura_verificada !== true) throw new Error('Entrada Slack não autenticada.');
const configuracao = {
  teamId: $env.APROVA_SLACK_TEAM_ID || '',
  channelId: $env.APROVA_SLACK_CANAL_CONSULTAS_ID || '',
  appId: $env.APROVA_SLACK_APP_ID || '',
};
if (!/^T[A-Z0-9]+$/.test(configuracao.teamId) ||
    !/^[CG][A-Z0-9]+$/.test(configuracao.channelId) ||
    !/^A[A-Z0-9]+$/.test(configuracao.appId)) {
  throw new Error('Configure APROVA_SLACK_TEAM_ID, APROVA_SLACK_CANAL_CONSULTAS_ID e APROVA_SLACK_APP_ID no ambiente.');
}
const envelope = entrada.envelope;
const evento = envelope?.event;
if (envelope?.type !== 'event_callback' ||
    envelope.team_id !== configuracao.teamId ||
    envelope.api_app_id !== configuracao.appId ||
    !evento || evento.bot_id || evento.bot_profile || evento.subtype ||
    typeof evento.user !== 'string' || !/^[UW][A-Z0-9]+$/.test(evento.user)) return [];
const dm = evento.type === 'message' && evento.channel_type === 'im' &&
  typeof evento.channel === 'string' && /^D[A-Z0-9]+$/.test(evento.channel);
const canal = evento.type === 'app_mention' && evento.channel === configuracao.channelId;
if (!dm && !canal) return [];
if (typeof envelope.event_id !== 'string' || !/^Ev[A-Za-z0-9]+$/.test(envelope.event_id)) {
  throw new Error('Evento Slack sem identificador válido.');
}
if (typeof evento.ts !== 'string' || !/^\d+\.\d{6}$/.test(evento.ts)) {
  throw new Error('Identificador da mensagem Slack inválido.');
}
const textoOriginal = typeof evento.text === 'string' ? evento.text : '';
const texto = (dm ? textoOriginal : textoOriginal.replace(/<@[UW][A-Z0-9]+>/, '')).trim();
if (!texto) return [];
if (texto.length > 6000) throw new Error('Pergunta excede o limite de 6000 caracteres.');
const tipo = dm ? 'dm' : 'canal';
return [{ json: {
  chatInput: texto,
  sessionId: ['slack', tipo, envelope.team_id, evento.channel, evento.user].join(':'),
  dedupe_key: envelope.team_id + ':' + envelope.event_id,
  recebido_em: entrada.meta.recebido_em,
  slack: {
    tipo_conversa: tipo,
    team_id: envelope.team_id,
    app_id: envelope.api_app_id,
    channel: evento.channel,
    user: evento.user,
    ts: evento.ts,
    event_id: envelope.event_id,
  },
} }];

const origem = $('04 | Preparar Consulta do Slack').first().json;
const texto = $json.output;
if (typeof texto !== 'string' || !texto.trim()) throw new Error('O agente não retornou uma resposta textual.');
if (!origem.slack?.channel || !['dm', 'canal'].includes(origem.slack.tipo_conversa)) {
  throw new Error('Destino Slack indisponível.');
}
const resposta = texto.trim().slice(0, 3500).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return [{ json: { slack: origem.slack, resposta } }];
